-- Additive optional Vocabulary artwork capability for B1/B1+.
-- No stored documents, releases, heads, content or compatibility hashes change.
-- Preserve migration 064 validation verbatim; extend only its raster catalog.
-- Migration 065's optional font/settings validator remains the called function.
create or replace function builder_b1_vocabulary_ui_bindings()
returns jsonb language sql immutable as $$
 select '{"navibar.vocabulary.active":"raster","navibar.vocabulary.disabled":"raster","navibar.vocabulary.pressed":"raster"}'::jsonb
$$;

create or replace function builder_b1_ui_projection_integrity(ui jsonb, component_slug text)
returns boolean language plpgsql immutable as $$
declare binding record; family text; asset jsonb; extension text; media_type text; title_count int;
 catalog constant jsonb := '{"background.main":"raster","background.students-book-parts":"raster","background.workbook-parts":"raster","background.grammar-book-parts":"raster","branding.publisher-logo":"raster","title.gaf":"gaf","title.sd.1":"png","title.sd.2":"png","title.hd.1":"png","title.hd.2":"png","navigation.back":"raster","navigation.check":"raster","navigation.home":"raster","navigation.next":"raster","navigation.previous":"raster","navigation.close":"raster","navigation.minimize":"raster","navigation.settings":"raster","navigation.video":"raster","navigation.videoWorksheet":"raster","navigation.showText":"raster","navigation.showTextPressed":"raster","navigation.previousInternal":"raster","navigation.previousInternalDisabled":"raster","navigation.nextInternal":"raster","navigation.nextInternalDisabled":"raster","navibar.sb.active":"raster","navibar.gb.active":"raster","navibar.workbook.active":"raster","navibar.reload.active":"raster","navibar.reload.pressed":"raster","navibar.reload.disabled":"raster","navibar.show.all.active":"raster","navibar.show.all.pressed":"raster","navibar.show.all.disabled":"raster","navibar.show.next.active":"raster","navibar.show.next.pressed":"raster","navibar.show.next.disabled":"raster","unit.1.normal":"raster","unit.1.active":"raster","unit.2.normal":"raster","unit.2.active":"raster","unit.3.normal":"raster","unit.3.active":"raster","unit.4.normal":"raster","unit.4.active":"raster","unit.5.normal":"raster","unit.5.active":"raster","unit.6.normal":"raster","unit.6.active":"raster","unit.7.normal":"raster","unit.7.active":"raster","unit.8.normal":"raster","unit.8.active":"raster","unit.9.normal":"raster","unit.9.active":"raster","unit.10.normal":"raster","unit.10.active":"raster","edition.students-book.normal":"raster","edition.students-book.active":"raster","edition.workbook.normal":"raster","edition.workbook.active":"raster","edition.grammar-book.normal":"raster","edition.grammar-book.active":"raster","edition.extras.normal":"raster","edition.extras.active":"raster","extras.progress-checks.normal":"raster","extras.progress-checks.active":"raster","extras.reviews.normal":"raster","extras.reviews.active":"raster","extras.practice.normal":"raster","extras.practice.active":"raster","extras.videos.normal":"raster","extras.videos.active":"raster","extras.extra-videos.normal":"raster","extras.extra-videos.active":"raster","extras.word-lists.normal":"raster","extras.word-lists.active":"raster","extras.tests.normal":"raster","extras.tests.active":"raster","extras.games.normal":"raster","extras.games.active":"raster","extras.grammar-reference.normal":"raster","extras.grammar-reference.active":"raster","extras.irregular-verbs.normal":"raster","extras.irregular-verbs.active":"raster","extras.writing-bank.normal":"raster","extras.writing-bank.active":"raster","extras.speaking-bank.normal":"raster","extras.speaking-bank.active":"raster","extras.extra-tasks-for-early-finishers.normal":"raster","extras.extra-tasks-for-early-finishers.active":"raster","extras.worksheets-for-videos.normal":"raster","extras.worksheets-for-videos.active":"raster","toolbar.mouse.normal":"raster","toolbar.mouse.active":"raster","toolbar.pencil.normal":"raster","toolbar.pencil.active":"raster","toolbar.marker.normal":"raster","toolbar.marker.active":"raster","toolbar.eraser.normal":"raster","toolbar.eraser.active":"raster","toolbar.clear.normal":"raster","toolbar.clear.active":"raster","toolbar.zoom.normal":"raster","toolbar.zoom.active":"raster","toolbar.hide.normal":"raster","toolbar.hide.active":"raster","toolbar.show.normal":"raster","toolbar.show.active":"raster","toolbar.undo.normal":"raster","toolbar.undo.active":"raster","toolbar.redo.normal":"raster","toolbar.redo.active":"raster","toolbar.text.normal":"raster","toolbar.text.active":"raster","toolbar.annotations.normal":"raster","toolbar.annotations.active":"raster","toolbar.url.normal":"raster","toolbar.url.active":"raster","toolbar.save.normal":"raster","toolbar.save.active":"raster","toolbar.load.normal":"raster","toolbar.load.active":"raster","toolbar.timer.normal":"raster","toolbar.timer.active":"raster","toolbar.score.normal":"raster","toolbar.score.active":"raster","toolbar.print.normal":"raster","toolbar.print.active":"raster","toolbar.keyboard.normal":"raster","toolbar.keyboard.active":"raster","control.activity-hotspot":"raster","media-player.background":"raster","media-player.playActive":"raster","media-player.playPressed":"raster","media-player.pauseActive":"raster","media-player.pausePressed":"raster","media-player.stopActive":"raster","media-player.stopPressed":"raster","sound.button":"audio","sound.correct":"audio","sound.incorrect":"audio","sound.page-turn":"audio"}'::jsonb || builder_b1_vocabulary_ui_bindings();
begin
 if not builder_b1_overview_ui_settings_integrity(ui) or ui->>'schemaVersion'<>'1.0'
   or ui->>'packageId' is distinct from component_slug or jsonb_typeof(ui->'assets') is distinct from 'object' then return false; end if;
 for binding in select * from jsonb_each(ui->'assets') loop
   family:=catalog->>binding.key; asset:=binding.value; extension:=asset->>'extension'; media_type:=asset->>'mediaType';
   if family is null or not builder_publication_exact_keys(asset,array['sha256','extension','mediaType','sizeBytes','width','height'])
     or coalesce(asset->>'sha256','')!~'^[a-f0-9]{64}$'
     or jsonb_typeof(asset->'sizeBytes')<>'number' or (asset->>'sizeBytes')!~'^[1-9][0-9]*$'
     or (asset->>'sizeBytes')::bigint>(case family when 'audio' then 12582912 when 'gaf' then 8388608 else 16777216 end)
     or media_type is distinct from (case extension when 'png' then 'image/png' when 'jpg' then 'image/jpeg' when 'webp' then 'image/webp' when 'mp3' then 'audio/mpeg' when 'wav' then 'audio/wav' when 'gaf' then 'application/x-gaf' end)
     or not (case family when 'raster' then extension in ('png','jpg','webp') when 'png' then extension='png' when 'audio' then extension in ('mp3','wav') when 'gaf' then extension='gaf' else false end) then return false; end if;
   if family in ('raster','png') then
     if jsonb_typeof(asset->'width')<>'number' or jsonb_typeof(asset->'height')<>'number'
       or (asset->>'width')!~'^[1-9][0-9]*$' or (asset->>'height')!~'^[1-9][0-9]*$'
       or (asset->>'width')::bigint>32768 or (asset->>'height')::bigint>32768 then return false; end if;
   elsif asset->'width'<>'null'::jsonb or asset->'height'<>'null'::jsonb then return false; end if;
 end loop;
 select count(*) into title_count from jsonb_object_keys(ui->'assets') k where k in ('title.gaf','title.sd.1','title.sd.2','title.hd.1','title.hd.2');
 if title_count not in (0,5) then return false; end if;
 if exists(select 1 from jsonb_each(ui->'assets') a join jsonb_each(ui->'assets') b on a.value->>'sha256'=b.value->>'sha256' and a.value->>'extension'=b.value->>'extension' where a.value<>b.value) then return false; end if;
 return true;
exception when others then return false;
end $$;
